<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$no='PT-'.date('ym').'-'.strtoupper(bin2hex(random_bytes(3)));$st=$pdo->prepare('INSERT INTO patients(patient_no,full_name,phone,date_of_birth,gender,address,next_of_kin,next_of_kin_phone) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$no,trim($_POST['full_name']),trim($_POST['phone']??''),($_POST['date_of_birth']??'')?:null,$_POST['gender']??'Unknown',trim($_POST['address']??''),trim($_POST['next_of_kin']??''),trim($_POST['next_of_kin_phone']??'')]);audit('create','patient',(int)$pdo->lastInsertId(),$no);flash('Patient registered successfully: '.$no);redirect('patients.php');}
$search=trim($_GET['q']??'');$sql='SELECT * FROM patients';$params=[];if($search!==''){$sql.=' WHERE full_name LIKE ? OR patient_no LIKE ? OR phone LIKE ?';$like='%'.$search.'%';$params=[$like,$like,$like];}$sql.=' ORDER BY id DESC LIMIT 100';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();admin_header('Patients','patients.php');?><div class="pagehead"><div><h1>Patients</h1><div class="muted">Registration and master patient index.</div></div><a class="btn" href="?action=new">Register patient</a></div><?php if(($_GET['action']??'')==='new'):?><div class="card" style="margin-bottom:18px"><h2>Register patient</h2><form method="post"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Full name</label><input name="full_name" required></div><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>Date of birth</label><input type="date" name="date_of_birth"></div><div class="field"><label>Gender</label><select name="gender"><option>Unknown</option><option>Female</option><option>Male</option><option>Other</option></select></div><div class="field full"><label>Address</label><input name="address"></div><div class="field"><label>Next of kin</label><input name="next_of_kin"></div><div class="field"><label>Next-of-kin phone</label><input name="next_of_kin_phone"></div></div><button style="margin-top:14px">Save patient</button></form></div><?php endif;?><form class="search"><input name="q" value="<?=e($search)?>" placeholder="Search patient name, number or phone"><button>Search</button></form><div class="card table-wrap"><table class="table"><tr><th>Patient No.</th><th>Name</th><th>Phone</th><th>DOB</th><th>Gender</th><th>Registered</th></tr><?php foreach($rows as $r):?><tr><td><a href="patient.php?id=<?=$r['id']?>"><?=e($r['patient_no'])?></a></td><td><?=e($r['full_name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['date_of_birth'])?></td><td><?=e($r['gender'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div><?php admin_footer();
